from urban_micro import hotspot_summary
import json
def panel(by, key, ch=0.0):
    return ('{"by":"%s","key":"%s","limit":1.000000,"cost":1.000000,"n":1,'
            '"baseline":30.000000,"post":30.000000,"change":%.6f}') % (by,key,ch)
def report(groups):
    return '{"alpha":0.050000,"groups":[%s]}\n' % ",".join(groups)

rep16 = report([panel("region", f"r{i:02d}") for i in range(16)])
out = hotspot_summary(rep16, {("region", f"r{i:02d}"):1.0 for i in range(16)})
print("16 panels ok, p=", json.loads(out)["groups"][0]["p"])

rep_mix = report([panel("region",f"r{i:02d}") for i in range(2)] +
                 [panel("window",f"w{i:02d}") for i in range(17)])
w = {("region",f"r{i:02d}"):1.0 for i in range(2)} | {("window",f"w{i:02d}"):1.0 for i in range(17)}
try:
    hotspot_summary(rep_mix, w); print("FAIL 17 windows accepted")
except ValueError: print("17 windows ok ValueError")

rep_mix16 = report([panel("region",f"r{i:02d}") for i in range(16)] +
                   [panel("window",f"w{i:02d}") for i in range(16)])
w16 = {("region",f"r{i:02d}"):1.0 for i in range(16)} | {("window",f"w{i:02d}"):1.0 for i in range(16)}
out = hotspot_summary(rep_mix16, w16)
print("16+16 ok, groups:", len(json.loads(out)["groups"]))
